function divisibleTriples(nums: number[], d: number): number {
  const n = nums.length;
  let count = 0;
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      for (let k = j + 1; k < n; k++)
        if ((nums[i] + nums[j] + nums[k]) % d === 0) count++;
  return count;
}

