function divisibleTriples(nums: number[], d: number): number {
  const seen = new Map<number, number>();
  let count = 0;
  for (let j = 0; j < nums.length; j++) {
    for (let k = j + 1; k < nums.length; k++) {
      const need = (d - ((nums[j] + nums[k]) % d)) % d;
      count += seen.get(need) ?? 0;
    }
    const rj = nums[j] % d;
    seen.set(rj, (seen.get(rj) ?? 0) + 1);
  }
  return count;
}

